import { mkdtemp, readFile, writeFile } from "node:fs/promises";
import { tmpdir } from "node:os";
import path from "node:path";
import { describe, expect, it } from "vitest";
import { parseAuthorProjectConfig } from "@clash-route-kit/core";
import { importIni } from "../src/program.js";

describe("CLI importIni", () => {
  it("writes a schema v2 draft from a SubConverter INI", async () => {
    const root = await mkdtemp(path.join(tmpdir(), "route-kit-import-"));
    const ini = [
      "; Generated by ClashRouteKit",
      "[custom]",
      "; 海外类目",
      "ruleset=AI,[]GEOSITE,openai",
      "ruleset=AI,[]FINAL",
      "custom_proxy_group=AI`select`[]DIRECT",
      "enable_rule_generator=true",
      "",
    ].join("\n");
    await writeFile(path.join(root, "in.ini"), ini, "utf8");

    const result = await importIni({ root, configFile: "routes.yaml", iniFile: "in.ini" });

    expect(result.proxyGroups).toBe(1);
    expect(result.routes).toBe(2);
    expect(result.warnings).toEqual([]);
    expect(result.outputPath).toBe(path.join(root, "output", "imported-routes-v2.yaml"));

    const yaml = await readFile(result.outputPath, "utf8");
    // 产出必须可被 v2 解析链直接读取
    const parsed = parseAuthorProjectConfig(yaml);
    expect(parsed.v2).toBeDefined();
    expect(parsed.v2?.proxyGroups[0]?.id).toBe("ai");
    expect(parsed.v2?.routes.map((route) => route.id)).toEqual(["openai", "final"]);
    expect(parsed.v2?.routes[0]?.policy).toEqual({ group: "ai" });
  });
});
